(()=>{'use strict';
const $=id=>document.getElementById(id);let snapshot=null,busy=false;const fmt=new Intl.NumberFormat('en-US',{maximumFractionDigits:2});const usd=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});const time=new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Singapore',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const valid=x=>typeof x==='number'&&Number.isFinite(x);const f=x=>valid(x)?fmt.format(x):'—';const money=x=>valid(x)?usd.format(x):'—';const at=x=>x?time.format(new Date(x)):'時間未提供';const signed=x=>valid(x)?(x>0?'+':'')+fmt.format(x):'—';const pct=x=>valid(x)?(x*100).toFixed(4)+'%':'—';
function old(m){return !m||!m.asof||Date.now()-m.asof>900000||m.status==='stale';}
function spark(points){if(!Array.isArray(points)||points.length<2)return '<p class="muted">尚無序列</p>';const values=points.map(p=>p[1]);if(!values.every(valid))return '';let lo=Math.min(...values),hi=Math.max(...values);if(hi===lo){lo-=.01;hi+=.01;}const xy=values.map((v,i)=>`${(i/(values.length-1)*300).toFixed(2)},${(76-(v-lo)/(hi-lo)*65).toFixed(2)}`).join(' ');return `<svg viewBox="0 0 300 85" role="img" aria-label="${esc('數值走勢，最低 '+f(lo)+'，最高 '+f(hi))}"><polyline points="${xy}"/></svg><small>${f(lo)} — ${f(hi)} · ${at(points[0][0])} → ${at(points.at(-1)[0])}</small>`;}
function cell(m,type){if(!m||m.status==='unavailable'||!valid(m.value))return '<span class="muted">未提供</span><small>來源不支援／暫時不可用</small>';let text=type==='funding'?pct(m.value):type==='oi'?money(m.value):f(m.value);let note='';if(type==='funding')note=`<small>${esc(m.rate_kind)} · ${valid(m.interval_hours)?f(m.interval_hours)+'h／期':'週期未確認'}<br>結算 ${at(m.next_time)}</small>`;return `<strong>${text}</strong><small>${old(m)?'⚠ 舊資料 · ':''}${at(m.asof)}</small>${note}`;}
function render(){const m=snapshot?.market_indicators;if(!m||m.status==='loading'){ $('marketStatus').textContent='指標採集中；尚無完整資料。';return;}const age=Date.now()-Date.parse(m.asof);const transportStale=snapshot.delivery?.mode==='cached';$('marketStatus').classList.toggle('stale',age>180000||transportStale);const count=m.contracts.filter(r=>r.metrics.accounts?.status!=='unavailable'&&r.metrics.funding?.status!=='unavailable').length;$('marketStatus').textContent=`指標採集截止 ${at(m.asof)}（北京／新加坡時間） · ${count}/${m.contracts.length} 組合約可讀${age>180000||transportStale?' · 上次資料，尚未確認更新':''} · 各項來源時間見下方`;
const x=m.extra||{},d=x.daily,price=x.price?.value;const ma=d?.ma120;const dist=valid(price)&&valid(ma)?(price/ma-1)*100:null;
$('overview').innerHTML=[['BTC / USDT',money(price),x.price?at(x.price.asof)+' · 本機接收':'來源暫時不可用'],['MA120 · 已收盤日線',money(ma),valid(dist)?`現價距離 ${signed(dist)}% · ${at(d.asof)}`:'來源暫時不可用'],['RSI 14 · 日線',f(d?.rsi14),d?at(d.asof)+' · Wilder 計算':'來源暫時不可用'],['MA20 / MA60',`${money(d?.ma20)} / ${money(d?.ma60)}`,d?'UTC 日線 · 僅已收盤 K 棒':'來源暫時不可用']].map(([label,value,caption])=>`<article class="stat"><span class="muted">${label}</span><strong>${value}</strong><small>${caption}</small></article>`).join('');
const rows=m.contracts.filter(r=>($('exchangeFilter').value==='all'||r.exchange===$('exchangeFilter').value)&&($('marginFilter').value==='all'||r.margin===$('marginFilter').value));
$('contractRows').innerHTML=rows.map(r=>`<tr><td><b>${esc(r.exchange)}</b><br>${esc(r.instrument)}<small>${esc(r.margin)}<br>多空比：${esc(r.ratio_scope||"單一合約")}</small></td>${['accounts','top_accounts','top_positions','funding','oi'].map(k=>`<td>${cell(r.metrics[k],k)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="6">此篩選沒有合約</td></tr>';
const type=$('ratioType').value;$('ratioCharts').innerHTML=rows.map(r=>{const v=r.metrics[type];return `<article class="chart-card"><b>${esc(r.exchange)} · ${esc(r.instrument)}</b><strong>${v?.status==='unavailable'?'—':f(v?.value)}</strong>${spark(v?.history)}${old(v)&&v?.status!=='unavailable'?'<small>⚠ 來源資料較舊</small>':''}</article>`;}).join('');
const flow=x.flow;$('flowPanel').innerHTML=(flow?`<p>24h 主動成交差額 · USDT</p><h2 class="${flow.value>=0?'positive':'negative'}">${signed(flow.value)}</h2><small>${esc(flow.definition)}<br>${at(flow.start)} → ${at(flow.asof)}</small>${spark(flow.history)}`:'<p>現貨成交資料暫時不可用</p>')+(x.premiums||[]).map(r=>`<div class="line-item"><span>${esc(r.exchange)} 報價差<small>${at(r.asof)} · ${esc(r.time_kind)}</small></span><b class="${r.difference>=0?'positive':'negative'}">${signed(r.difference)} USD <small>${signed(r.percent)}%</small></b></div>`).join('');
const depth=x.depth;if(depth){const max=Math.max(...depth.bids.map(r=>r[0]*r[1]),...depth.asks.map(r=>r[0]*r[1]));$('depthPanel').innerHTML=`<div class="line-item"><span>買盤 ${money(depth.bid_usd)}</span><span>賣盤 ${money(depth.ask_usd)}</span></div><small>±0.5% 掛單差額比例 ${valid(depth.imbalance)?signed(depth.imbalance*100)+'%':'—'} · ${at(depth.asof)}（本機接收）</small><p class="note">${depth.coverage_complete?'兩側已涵蓋 ±0.5% 範圍':'⚠ 深度截斷：買側僅 '+f(depth.bid_edge_pct)+'%、賣側僅 '+f(depth.ask_edge_pct)+'%；以下是已取得範圍，非完整 ±0.5%'}。</p>`+['bids','asks'].map(side=>`<small>${side==='bids'?'主要買單':'主要賣單'} · 按掛單名義金額排序</small>`+depth[side].map(([p,q])=>`<div class="wall-row"><span>${f(p)}</span><div class="wall ${side==='asks'?'ask':''}" style="width:${(p*q/max*100).toFixed(2)}%"></div><span>${money(p*q)}</span></div>`).join('')).join('');}else $('depthPanel').innerHTML='<p>訂單簿資料暫時不可用</p>';
}
async function refresh(manual=false){if(busy)return;busy=true;$('refreshMarket').disabled=true;$('refreshMarket').textContent=manual?'讀取中…':'更新資料';try{snapshot=await window.portfolioVault.getJson('/api/latest',{forceRefresh:true,forceCollect:manual});render();}catch(e){$('marketStatus').textContent='更新未完成：'+(e.message||'資料通道暫時不可用')+'；保留上次資料。';$('marketStatus').classList.add('stale');}finally{busy=false;$('refreshMarket').disabled=false;$('refreshMarket').textContent='更新資料';}}
$('portfolioLink').href='./'+location.hash;['exchangeFilter','marginFilter','ratioType'].forEach(id=>$(id).addEventListener('change',render));$('refreshMarket').addEventListener('click',()=>refresh(true));
(async()=>{try{const local=await window.portfolioVault.getLocalSnapshot?.();if(local){snapshot={...local.latest,delivery:{mode:'cached'}};render();}}catch{}await refresh();})();setInterval(()=>{if(!document.hidden)refresh();},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
})();
